import{_ as e,o,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const v=JSON.parse('{"title":"Persistir colunas visíveis do Relatório Geral","description":"","frontmatter":{"title":"Persistir colunas visíveis do Relatório Geral","id":"eproc-persistir-colunas-relatorio","plataforma":"eproc","grupo":"Relatórios","plano":"free","desde":"1.4.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-persistir-colunas-relatorio.md","filePath":"funcionalidades/eproc-persistir-colunas-relatorio.md"}'),i={name:"funcionalidades/eproc-persistir-colunas-relatorio.md"};function l(t,a,c,n,u,d){return o(),s("div",null,a[0]||(a[0]=[r('<h1 id="persistir-colunas-visiveis-do-relatorio-geral" tabindex="-1">Persistir colunas visíveis do Relatório Geral <a class="header-anchor" href="#persistir-colunas-visiveis-do-relatorio-geral" aria-label="Permalink to &quot;Persistir colunas visíveis do Relatório Geral&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>No Relatório Geral, o eproc permite escolher as colunas visíveis, mas com frequência volta ao padrão sozinho. Este recurso memoriza as colunas que você escolheu e as reaplica quando o eproc as reseta, avisando quando faz isso.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, Relatório Geral de Processos, seletor &quot;Colunas visíveis&quot;.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Gere o Relatório Geral e ajuste as colunas em &quot;Colunas visíveis&quot;. Um balão confirma: &quot;O eploc vai lembrar dessa coluna para você&quot;.</li><li>Quando o eproc resetar as colunas, o eploc as remarca, recarrega a tabela e avisa no botão &quot;Colunas visíveis&quot;: &quot;O sistema resetou as colunas — mas o eploc já corrigiu pra você&quot;.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Nada é alterado antes de você mexer numa coluna pela primeira vez com o recurso ligado.</li><li>As colunas são guardadas separadamente para cada perfil/unidade do eproc.</li><li>A correção é feita uma coluna por vez. Com várias colunas resetadas, ela leva alguns instantes.</li></ul>',11)]))}const h=e(i,[["render",l]]);export{v as __pageData,h as default};
